// Welcome Portfolio
// A click handler updates visible text; this is the smallest useful interaction.
document.querySelector("#go").addEventListener("click",()=>document.querySelector("#out").textContent="Hello from Code Academy!");

// Profile &amp; Preferences
// Trim input and update text safely; textContent avoids treating user text as HTML.
document.querySelector("#go").addEventListener("click",()=>{const name=document.querySelector("#entry").value.trim();if(!name){document.querySelector("#out").textContent="Enter a display name.";return;}document.querySelector("#name").textContent=name;document.querySelector("#out").textContent="Profile updated locally.";});

// Validated Registration Form
// Validate the range before accepting a score.
document.querySelector("#go").addEventListener("click",()=>{const raw=document.querySelector("#entry").value,n=Number(raw);document.querySelector("#out").textContent=raw.trim()!==""&&Number.isFinite(n)&&n>=0&&n<=100?`Accepted score: ${n}/100`:"Enter a score from 0 to 100.";});

// Pocket Calculator
// Keep operations explicit and avoid dividing by zero.
document.querySelector("#go").addEventListener("click",()=>{const a=Number(document.querySelector("#a").value),b=Number(document.querySelector("#b").value),op=document.querySelector("#op").value;if(op==="/"&&b===0){document.querySelector("#out").textContent="Cannot divide by zero.";return;}const r=op==="+"?a+b:op==="-"?a-b:op==="*"?a*b:a/b;document.querySelector("#out").textContent=`Result: ${r}`;});

// Searchable Skill Catalog
// Filter a collection from one source of truth.
const skills=["HTML","CSS","JavaScript","Python","Accessibility","Testing"];function render(){const q=document.querySelector("#entry").value.toLowerCase().trim(),found=skills.filter(s=>s.toLowerCase().includes(q));document.querySelector("#list").innerHTML=found.map(s=>`<div class="row">${s}</div>`).join("")||"<p class=muted>No matches.</p>";}document.querySelector("#entry").addEventListener("input",render);render();

// Study Planner
// A reusable pure function makes a rule easy to reason about and test.
const breakMinutes=m=>m>=50?10:m>=25?5:0;document.querySelector("#go").addEventListener("click",()=>{const m=Number(document.querySelector("#entry").value);document.querySelector("#out").textContent=Number.isFinite(m)&&m>=0?`Study ${m} minutes; suggested break: ${breakMinutes(m)} minutes.`:"Enter a valid duration.";});

// Expense Insights Dashboard
// localStorage stores only this demo's non-sensitive sample data.
const key="ca-ready-expenses-v1";let data=JSON.parse(localStorage.getItem(key)||"[]");function render(){document.querySelector("#list").innerHTML=data.map(x=>`<div class=row>${x.label}: ${x.amount.toFixed(2)}</div>`).join("");document.querySelector("#out").textContent=`Total: ${data.reduce((s,x)=>s+x.amount,0).toFixed(2)} · ${data.length} records`;}document.querySelector("#go").addEventListener("click",()=>{const label=document.querySelector("#entry").value.trim(),amount=Number(document.querySelector("#amount").value);if(!label||!Number.isFinite(amount)||amount<=0)return;data.push({label,amount});localStorage.setItem(key,JSON.stringify(data));render();});render();

// Target Practice Mini Game
// Draw a target with canvas shapes; no download or library is required.
const c=document.querySelector("#game"),ctx=c.getContext("2d");let score=0,t={x:160,y:120};function draw(){ctx.fillStyle="#071225";ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle="#22d3ee";ctx.beginPath();ctx.arc(t.x,t.y,25,0,7);ctx.fill();ctx.fillStyle="#f8fafc";ctx.beginPath();ctx.arc(t.x,t.y,9,0,7);ctx.fill();}c.addEventListener("click",e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)*c.width/r.width,y=(e.clientY-r.top)*c.height/r.height;if(Math.hypot(x-t.x,y-t.y)<30){score++;t={x:35+Math.random()*(c.width-70),y:35+Math.random()*(c.height-70)};document.querySelector("#out").textContent=`Score: ${score}`;draw();}});document.querySelector("#go").addEventListener("click",()=>{score=0;document.querySelector("#out").textContent="Score: 0";draw();});draw();

// Inventory Cards
// Model inventory values as data, then calculate their total value.
const items=[{name:"Keyboard",qty:4,price:18.5},{name:"Notebook",qty:12,price:2.25}];const value=items.reduce((sum,item)=>sum+item.qty*item.price,0);document.querySelector("#out").textContent=`Inventory value: ${value.toFixed(2)} · ${items.length} item types`;

// Smart Search Directory
// Search across title and tag, not only the visible headline.
const projects=[{title:"Portfolio",tag:"web design"},{title:"Quiz Lab",tag:"learning"},{title:"Budget Board",tag:"data"},{title:"Space Defender",tag:"game"}];function render(){const q=document.querySelector("#entry").value.toLowerCase().trim(),found=projects.filter(p=>(p.title+" "+p.tag).toLowerCase().includes(q));document.querySelector("#list").innerHTML=found.map(p=>`<div class=row><strong>${p.title}</strong> · ${p.tag}</div>`).join("")||"<p class=muted>No matches.</p>";}document.querySelector("#entry").addEventListener("input",render);render();

// Task Board
// Render a task list from state so the completed counter stays accurate.
let tasks=[{title:"Plan",done:true},{title:"Build",done:false},{title:"Test",done:false}];function render(){document.querySelector("#list").innerHTML=tasks.map((t,i)=>`<div class=row><span>${t.done?"✓":"○"} ${t.title}</span><button data-i="${i}">${t.done?"Reopen":"Complete"}</button></div>`).join("");document.querySelector("#out").textContent=`${tasks.filter(t=>t.done).length}/${tasks.length} complete`;document.querySelectorAll("[data-i]").forEach(b=>b.onclick=()=>{tasks[Number(b.dataset.i)].done=!tasks[Number(b.dataset.i)].done;render();});}document.querySelector("#go").addEventListener("click",()=>{const title=document.querySelector("#entry").value.trim();if(title){tasks.push({title,done:false});render();}});render();

// Unit Converter
// Keep conversion formulas separate and reject non-numeric values.
document.querySelector("#go").addEventListener("click",()=>{const n=Number(document.querySelector("#entry").value),u=document.querySelector("#op").value;if(!Number.isFinite(n)){document.querySelector("#out").textContent="Enter a number.";return;}document.querySelector("#out").textContent=u==="km"?`${(n*.621371).toFixed(3)} miles`:u==="c"?`${(n*9/5+32).toFixed(1)} °F`:`${(n*2.20462).toFixed(2)} lb`;});

// Local Journal
// Local heuristic only: this is not a production password-strength meter.
document.querySelector("#go").addEventListener("click",()=>{const p=document.querySelector("#entry").value,checks=[p.length>=14,/[a-z]/.test(p),/[A-Z]/.test(p),/\d/.test(p),/[^A-Za-z0-9]/.test(p)];document.querySelector("#out").textContent=`${checks.filter(Boolean).length}/5 practice checks passed. Do not enter real credentials.`;});

// Password Safety Inspector
// Mock metrics are generated locally; real dashboards need authenticated data.
document.querySelector("#go").addEventListener("click",()=>{document.querySelector("#a").textContent=100+Math.floor(Math.random()*80);document.querySelector("#b").textContent=30+Math.floor(Math.random()*40);document.querySelector("#c").textContent=`${1+Math.floor(Math.random()*14)} days`;document.querySelector("#out").textContent="Updated simulated metrics.";});

// Grandmaster Space Defender Studio
// A keyboard-driven Canvas capstone using vector shapes, no assets needed.
const c=document.querySelector("#game"),ctx=c.getContext("2d");let player=360,shots=[],targets=[],score=0,keys=new Set(),tick=0;function reset(){player=360;shots=[];targets=[];score=0;document.querySelector("#out").textContent="Score: 0";}document.querySelector("#go").addEventListener("click",reset);window.addEventListener("keydown",e=>{keys.add(e.code);if(["ArrowLeft","ArrowRight","Space"].includes(e.code))e.preventDefault();});window.addEventListener("keyup",e=>keys.delete(e.code));function frame(){tick++;if(keys.has("ArrowLeft"))player=Math.max(18,player-5);if(keys.has("ArrowRight"))player=Math.min(c.width-18,player+5);if(keys.has("Space")&&tick%8===0)shots.push({x:player,y:c.height-35});if(tick%34===0)targets.push({x:20+Math.random()*(c.width-40),y:-8});shots.forEach(s=>s.y-=7);targets.forEach(t=>t.y+=2);for(let i=targets.length-1;i>=0;i--){const j=shots.findIndex(s=>Math.hypot(s.x-targets[i].x,s.y-targets[i].y)<16);if(j>=0){targets.splice(i,1);shots.splice(j,1);score++;document.querySelector("#out").textContent=`Score: ${score}`;}}shots=shots.filter(s=>s.y>-10);targets=targets.filter(t=>t.y<c.height+15);ctx.fillStyle="#071225";ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle="#22d3ee";ctx.fillRect(player-16,c.height-26,32,16);ctx.fillStyle="#fbbf24";shots.forEach(s=>ctx.fillRect(s.x-2,s.y,4,10));ctx.fillStyle="#fb7185";targets.forEach(t=>{ctx.beginPath();ctx.arc(t.x,t.y,10,0,7);ctx.fill();});requestAnimationFrame(frame);}reset();frame();

