// Skill Card Gallery
// Filter a collection from one source of truth.
const skills=["HTML","CSS","JavaScript","Python","Accessibility","Testing"];function render(){const q=document.querySelector("#entry").value.toLowerCase().trim(),found=skills.filter(s=>s.toLowerCase().includes(q));document.querySelector("#list").innerHTML=found.map(s=>`<div class="row">${s}</div>`).join("")||"<p class=muted>No matches.</p>";}document.querySelector("#entry").addEventListener("input",render);render();

