/* Responsive design tokens: change these first to theme the project. */
:root{color-scheme:dark;--bg:#071225;--panel:#0d1b31;--line:#294362;--text:#eef5ff;--muted:#a5bad3;--primary:#2563eb;--accent:#22d3ee;font-family:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:clamp(14px,4vw,38px);color:var(--text);background:radial-gradient(circle at 80% 0,#172d65,transparent 40%),var(--bg)}main{max-width:920px;margin:auto}.top{display:flex;align-items:center;gap:13px}.brand{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:linear-gradient(140deg,var(--primary),#7c3aed);font-weight:900}.eyebrow{color:var(--accent);font-size:10px;text-transform:uppercase;letter-spacing:2px;font-weight:900}h1{font-size:clamp(28px,5vw,46px);line-height:1.1;margin:12px 0}p{color:var(--muted);line-height:1.6}.panel{margin-top:22px;padding:clamp(18px,4vw,30px);background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:0 16px 45px #0004}button{background:linear-gradient(110deg,#2563eb,#6d4aff);color:white;border:0;border-radius:10px;padding:11px 15px;font-weight:800;cursor:pointer;margin:4px}input,select{background:#071225;border:1px solid #355270;border-radius:9px;padding:11px;color:var(--text);max-width:100%}label{display:grid;gap:7px;margin:12px 0}.result{border-left:3px solid var(--accent);padding:11px;background:#081a30;border-radius:7px}.muted{font-size:12px;color:var(--muted)}.row{display:flex;align-items:center;gap:9px;justify-content:space-between;margin:10px 0}.list{border:1px solid var(--line);border-radius:10px;padding:6px 12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.tile{padding:14px;border:1px solid var(--line);border-radius:12px;background:#071326}.avatar{width:60px;height:60px;border-radius:20px;background:#1d4ed8;display:grid;place-items:center;font-weight:900}@media(max-width:600px){body{padding:12px}.row{flex-wrap:wrap}input{width:100%}}canvas{display:block;width:100%;max-width:720px;border:1px solid var(--line);border-radius:12px;background:#071225}
/* Stage 6: experiment with a theme and test phone widths. */
:root{--primary:#2563eb;--accent:#22d3ee} .panel,.tile,.card{border-radius:16px;border-color:var(--primary)} button{background:linear-gradient(110deg,var(--primary),var(--accent))}

