// Analytics Dashboard
// localStorage stores only this demo's non-sensitive sample data.
const key="ca-ready-expenses-v1";let data=JSON.parse(localStorage.getItem(key)||"[]");function render(){document.querySelector("#list").innerHTML=data.map(x=>`<div class=row>${x.label}: ${x.amount.toFixed(2)}</div>`).join("");document.querySelector("#out").textContent=`Total: ${data.reduce((s,x)=>s+x.amount,0).toFixed(2)} · ${data.length} records`;}document.querySelector("#go").addEventListener("click",()=>{const label=document.querySelector("#entry").value.trim(),amount=Number(document.querySelector("#amount").value);if(!label||!Number.isFinite(amount)||amount<=0)return;data.push({label,amount});localStorage.setItem(key,JSON.stringify(data));render();});render();

