// Arcade Panel
// Draw a target with canvas shapes; no download or library is required.
const c=document.querySelector("#game"),ctx=c.getContext("2d");let score=0,t={x:160,y:120};function draw(){ctx.fillStyle="#071225";ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle="#22d3ee";ctx.beginPath();ctx.arc(t.x,t.y,25,0,7);ctx.fill();ctx.fillStyle="#f8fafc";ctx.beginPath();ctx.arc(t.x,t.y,9,0,7);ctx.fill();}c.addEventListener("click",e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)*c.width/r.width,y=(e.clientY-r.top)*c.height/r.height;if(Math.hypot(x-t.x,y-t.y)<30){score++;t={x:35+Math.random()*(c.width-70),y:35+Math.random()*(c.height-70)};document.querySelector("#out").textContent=`Score: ${score}`;draw();}});document.querySelector("#go").addEventListener("click",()=>{score=0;document.querySelector("#out").textContent="Score: 0";draw();});draw();

