// Inventory Board
// Model inventory values as data, then calculate their total value.
const items=[{name:"Keyboard",qty:4,price:18.5},{name:"Notebook",qty:12,price:2.25}];const value=items.reduce((sum,item)=>sum+item.qty*item.price,0);document.querySelector("#out").textContent=`Inventory value: ${value.toFixed(2)} · ${items.length} item types`;

