# 8 — Target practice game. Desktop setup: python -m pip install pygame.
# The PNG is optional; a vector target is drawn when the file is absent.
from pathlib import Path
import random, pygame
pygame.init(); screen=pygame.display.set_mode((800,500)); clock=pygame.time.Clock(); score=0; target=pygame.Rect(350,180,56,56)
p=Path("assets/target.png"); sprite=pygame.image.load(p).convert_alpha() if p.exists() else None
running=True
while running:
 for event in pygame.event.get():
  if event.type==pygame.QUIT: running=False
  elif event.type==pygame.MOUSEBUTTONDOWN and target.collidepoint(event.pos): score+=1; target.center=(random.randint(40,760),random.randint(60,450))
 screen.fill((7,18,37))
 if sprite: screen.blit(pygame.transform.smoothscale(sprite,target.size),target)
 else: pygame.draw.circle(screen,(34,211,238),target.center,28); pygame.draw.circle(screen,(248,250,252),target.center,9)
 font=pygame.font.Font(None,30); screen.blit(font.render(f"Score: {score} · click target",True,(226,232,240)),(18,14)); pygame.display.flip(); clock.tick(60)
pygame.quit()

