# 10 — Summarize CSV data without needing a file download.
import csv
from io import StringIO
raw="category,amount\nbooks,12\ndata,8\nbooks,5\n"
rows=list(csv.DictReader(StringIO(raw))); totals={}
for row in rows: totals[row["category"]]=totals.get(row["category"],0)+float(row["amount"])
for category,amount in sorted(totals.items()): print(category,round(amount,2))

race_simulator.py.content:
# 11 — GRAND PRIX: keyboard-controlled top-down racing game.
# Desktop setup: python -m pip install pygame; optional PNG assets are in assets/.
import random
from pathlib import Path
import pygame
pygame.init(); W,H=600,720; screen=pygame.display.set_mode((W,H)); pygame.display.set_caption("Code Academy · Neon Racer")
clock=pygame.time.Clock(); font=pygame.font.Font(None,28); player=pygame.Rect(W//2-24,H-120,48,76); rivals=[]; score=0; tick=0; speed=5; running=True
def load(name):
    path=Path("assets")/name
    return pygame.image.load(path).convert_alpha() if path.exists() else None
track=load("track.png"); car=load("player_car.png"); rival=load("rival_car.png")
while running:
    tick+=1
    for event in pygame.event.get():
        if event.type==pygame.QUIT: running=False
    keys=pygame.key.get_pressed(); player.x=max(85,min(W-133,player.x+(keys[pygame.K_RIGHT]-keys[pygame.K_LEFT])*7))
    if tick%42==0: rivals.append(pygame.Rect(random.choice([115,210,305,400]),-90,46,74))
    for other in rivals: other.y+=speed
    if any(player.colliderect(other) for other in rivals): speed=3; score=max(0,score-1)
    else: speed=5; score+=1
    rivals=[r for r in rivals if r.top<H+10]; screen.fill((7,18,37))
    if track: screen.blit(pygame.transform.scale(track,(W,H)),(0,0))
    else:
        pygame.draw.rect(screen,(40,50,65),(75,0,W-150,H)); pygame.draw.line(screen,(250,204,21),(W//2,0),(W//2,H),4)
    if car: screen.blit(pygame.transform.smoothscale(car,player.size),player)
    else: pygame.draw.rect(screen,(34,211,238),player,border_radius=9)
    for other in rivals:
        if rival: screen.blit(pygame.transform.smoothscale(rival,other.size),other)
        else: pygame.draw.rect(screen,(251,113,133),other,border_radius=8)
    screen.blit(font.render(f"Distance: {score} · ← → steer · avoid traffic",True,(248,250,252)),(12,12)); pygame.display.flip(); clock.tick(60)
pygame.quit()

test_quality_gate.py.content:
# 12 — Assertions catch broken assumptions while developing.
def total_cost(prices):
    if any(price<0 for price in prices): raise ValueError("Prices cannot be negative")
    return round(sum(prices),2)
assert total_cost([2.5,3])==5.5
assert total_cost([])==0.0
try: total_cost([4,-1])
except ValueError: print("Negative-price test passed.")
print("Quality checks passed.")

