# 15 — GRANDMASTER: Space Defender arcade game.
# Desktop setup: python -m pip install pygame. Optional artwork is in assets/.
import random
from pathlib import Path
import pygame
pygame.init(); W,H=900,560; screen=pygame.display.set_mode((W,H)); pygame.display.set_caption("Code Academy · Space Defender")
clock=pygame.time.Clock(); font=pygame.font.Font(None,28); player=pygame.Rect(W//2-20,H-70,40,28); shots=[]; enemies=[]; score=0; tick=0; running=True
def sprite(name):
 p=Path("assets")/name
 return pygame.image.load(p).convert_alpha() if p.exists() else None
ship=sprite("player_ship.png"); drone=sprite("enemy_drone.png")
while running:
 tick+=1
 for event in pygame.event.get():
  if event.type==pygame.QUIT: running=False
  elif event.type==pygame.KEYDOWN and event.key==pygame.K_SPACE: shots.append(pygame.Rect(player.centerx-3,player.top-12,6,14))
 keys=pygame.key.get_pressed(); player.x=max(0,min(W-player.width,player.x+(keys[pygame.K_RIGHT]-keys[pygame.K_LEFT])*6))
 if tick%38==0: enemies.append(pygame.Rect(random.randint(10,W-42),-24,32,24))
 for shot in shots: shot.y-=8
 for enemy in enemies: enemy.y+=2
 for enemy in enemies[:]:
  hit=next((s for s in shots if enemy.colliderect(s)),None)
  if hit: enemies.remove(enemy); shots.remove(hit); score+=10
  elif enemy.top>H: enemies.remove(enemy)
 shots=[s for s in shots if s.bottom>0]; screen.fill((5,12,30))
 for i in range(42): pygame.draw.circle(screen,(20,55,100),((i*97+tick//3)%W,(i*53+tick)%H),1)
 if ship: screen.blit(pygame.transform.smoothscale(ship,player.size),player)
 else: pygame.draw.polygon(screen,(34,211,238),[(player.centerx,player.top),(player.left,player.bottom),(player.right,player.bottom)])
 for e0 in enemies:
  if drone: screen.blit(pygame.transform.smoothscale(drone,e0.size),e0)
  else: pygame.draw.rect(screen,(251,113,133),e0,border_radius=6)
 for shot in shots: pygame.draw.rect(screen,(251,191,36),shot,border_radius=3)
 screen.blit(font.render(f"Score: {score} · Move ← → · Fire SPACE",True,(226,232,240)),(18,14)); pygame.display.flip(); clock.tick(60)
pygame.quit()

