-- Hello SQL — First Query
-- SQLite-compatible educational exercise; all names and data are fictional.
SELECT 'Hello from Code Academy' AS message;

-- Learner Table — Schema & Types
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS learners(id INTEGER PRIMARY KEY,name TEXT NOT NULL,xp INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO learners VALUES(1,'Amina',120),(2,'Kojo',85);
SELECT * FROM learners ORDER BY xp DESC;

-- Score Constraints — Data Validation
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS scores(learner TEXT NOT NULL,score INTEGER CHECK(score BETWEEN 0 AND 100));
INSERT INTO scores VALUES('Maya',86);
SELECT * FROM scores WHERE score BETWEEN 0 AND 100;

-- Sales Summary — Aggregate Functions
-- SQLite-compatible educational exercise; all names and data are fictional.
WITH sales(item,amount) AS (VALUES('Notebook',12.5),('Data bundle',8.0),('USB drive',25.0)) SELECT COUNT(*) AS items,ROUND(SUM(amount),2) AS total,ROUND(AVG(amount),2) AS average FROM sales;

-- Skill Explorer — WHERE & ORDER BY
-- SQLite-compatible educational exercise; all names and data are fictional.
WITH skills(name) AS (VALUES('HTML'),('CSS'),('JavaScript'),('Python')) SELECT name FROM skills WHERE length(name)>3 ORDER BY name;

-- Reusable View — Encapsulate Query Logic
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS learners(id INTEGER PRIMARY KEY,name TEXT,xp INTEGER); INSERT OR IGNORE INTO learners VALUES(1,'Amina',120),(2,'Kojo',85); CREATE VIEW IF NOT EXISTS learner_summary AS SELECT name,xp,CASE WHEN xp>=100 THEN 'Active' ELSE 'Growing' END AS status FROM learners; SELECT * FROM learner_summary ORDER BY xp DESC;

-- Data Insights — GROUP BY Metrics
-- SQLite-compatible educational exercise; all names and data are fictional.
WITH scores(score) AS (VALUES(72),(88),(94),(61),(85)) SELECT COUNT(*) AS count,SUM(score) AS total,ROUND(AVG(score),1) AS average,MAX(score) AS best FROM scores;

-- Game Leaderboard — Ranking
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS game_scores(player TEXT NOT NULL,score INTEGER NOT NULL CHECK(score>=0)); INSERT INTO game_scores VALUES('Player A',40),('Player B',65),('Player C',52); SELECT player,score,RANK() OVER(ORDER BY score DESC) AS rank FROM game_scores ORDER BY score DESC;

-- Course Model — Relational Joins
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS learners(id INTEGER PRIMARY KEY,name TEXT); CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY,title TEXT UNIQUE); CREATE TABLE IF NOT EXISTS enrollments(learner_id INTEGER,course_id INTEGER,completed INTEGER CHECK(completed IN(0,1)),FOREIGN KEY(learner_id) REFERENCES learners(id),FOREIGN KEY(course_id) REFERENCES courses(id)); INSERT OR IGNORE INTO learners VALUES(1,'Amina'),(2,'Kojo'); INSERT OR IGNORE INTO courses VALUES(1,'SQL Basics'),(2,'Data Reports'); INSERT INTO enrollments VALUES(1,1,1),(2,1,0),(1,2,0); SELECT learners.name,courses.title,enrollments.completed FROM enrollments JOIN learners ON learners.id=enrollments.learner_id JOIN courses ON courses.id=enrollments.course_id;

-- Directory Search — LIKE & Sort
-- SQLite-compatible educational exercise; all names and data are fictional.
WITH contacts(name,team) AS (VALUES('Amina','Design'),('Kojo','Engineering'),('Maya','Engineering'),('Ayo','Learning')) SELECT name,team FROM contacts WHERE lower(name) LIKE '%ma%' ORDER BY name;

-- Task Manager — INSERT & UPDATE
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,title TEXT NOT NULL,completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1))); INSERT INTO tasks(title,completed) VALUES('Plan',1),('Build',0),('Test',0); UPDATE tasks SET completed=1 WHERE title='Build'; SELECT title,CASE WHEN completed=1 THEN 'Done' ELSE 'Open' END AS status FROM tasks ORDER BY id;

-- Quality Gate — Constraints & Checks
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS quality_checks(name TEXT PRIMARY KEY,passed INTEGER CHECK(passed IN(0,1))); INSERT OR REPLACE INTO quality_checks VALUES('score range',1),('title not blank',1),('foreign key check',1); SELECT name,passed FROM quality_checks; SELECT CASE WHEN MIN(passed)=1 THEN 'All checks passed' ELSE 'Review failed checks' END AS test_result FROM quality_checks;

-- Journal Store — Structured Records
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); INSERT INTO notes(title,body) VALUES('SQL journal','Use transactions and constraints to protect data.'); SELECT * FROM notes ORDER BY id DESC LIMIT 5;

-- Grandmaster Capstone — Learning Analytics Report
-- SQLite-compatible educational exercise; all names and data are fictional.
CREATE TABLE IF NOT EXISTS learners(id INTEGER PRIMARY KEY,name TEXT NOT NULL,xp INTEGER NOT NULL CHECK(xp>=0)); CREATE TABLE IF NOT EXISTS project_runs(learner_id INTEGER NOT NULL,project TEXT NOT NULL,passed INTEGER NOT NULL CHECK(passed IN(0,1)),FOREIGN KEY(learner_id) REFERENCES learners(id)); INSERT OR IGNORE INTO learners VALUES(1,'Amina',240),(2,'Kojo',180),(3,'Maya',310); INSERT INTO project_runs VALUES(1,'Calculator',1),(1,'Tasks',1),(2,'Calculator',1),(2,'Grandmaster',0),(3,'Calculator',1),(3,'Grandmaster',1); SELECT l.name,l.xp,COUNT(p.project) AS attempted,SUM(p.passed) AS passed,ROUND(100.0*SUM(p.passed)/COUNT(p.project),1) AS pass_rate FROM learners l LEFT JOIN project_runs p ON p.learner_id=l.id GROUP BY l.id,l.name,l.xp ORDER BY l.xp DESC;
